"""Exam question on the sigma-algebra generated by a family of sets on a finite universe.

The stem gives U = {1, ..., n}, a family F of two or three subsets that is not closed, and a measure mu given by a
weight for each point. Four parts:

(a) the number of atoms of sigma(F) (its minimal non-empty sets)            number (whole), 2 marks
(b) the number of sets in sigma(F), 2^(atoms)                               number (whole), 1 mark, follow_through 2^part_a
(c) how many sets of sigma(F) are not in F, |sigma(F)| - |F|                number (whole), 1 mark, follow_through part_b - |F|
(d) mu(E) for a stated set E built from F by complement, union, intersection  number (whole), 2 marks

The atoms are the non-empty classes of points that belong to exactly the same members of F. Every key is checked by
a second route: sigma(F) is built by closing F under complement and union until nothing new appears, and its size
and its minimal members must agree with 2^(atoms) and the atoms.
"""

from __future__ import annotations

import random
from itertools import combinations

from ..core import VerificationError, attempts, check, generator, phrase
from .exd_x_r2h_support import build_part

_UNIVERSE_SIZES = (6, 7, 8)

# (text, evaluator over (A, B, C, U), needs C, wrong readings as (text, evaluator, misconception id))
_COMPLEMENT = "^c"


def _comp(s, u):
    return u - s


_TEMPLATES = (
    (
        "A ∩ B^c",
        lambda A, B, C, U: A & (U - B),
        False,
        (
            ("A ∪ B^c", lambda A, B, C, U: A | (U - B), "union-read-as-intersection"),
            ("A ∩ B", lambda A, B, C, U: A & B, "complement-dropped"),
            ("(A ∩ B)^c", lambda A, B, C, U: U - (A & B), "complement-misplaced"),
        ),
    ),
    (
        "A ∪ B^c",
        lambda A, B, C, U: A | (U - B),
        False,
        (
            ("A ∩ B^c", lambda A, B, C, U: A & (U - B), "union-read-as-intersection"),
            ("A ∪ B", lambda A, B, C, U: A | B, "complement-dropped"),
            ("(A ∪ B)^c", lambda A, B, C, U: U - (A | B), "complement-misplaced"),
        ),
    ),
    (
        "(A ∪ B)^c",
        lambda A, B, C, U: U - (A | B),
        False,
        (
            ("A^c ∪ B^c", lambda A, B, C, U: (U - A) | (U - B), "de-morgan-not-swapped"),
            ("A ∪ B", lambda A, B, C, U: A | B, "complement-dropped"),
            ("A^c ∩ B", lambda A, B, C, U: (U - A) & B, "complement-misplaced"),
        ),
    ),
    (
        "(A − B) ∪ (B − A)",
        lambda A, B, C, U: A ^ B,
        False,
        (
            ("A ∪ B", lambda A, B, C, U: A | B, "symmetric-difference-as-union"),
            ("A ∩ B", lambda A, B, C, U: A & B, "symmetric-difference-as-intersection"),
            ("A − B", lambda A, B, C, U: A - B, "symmetric-difference-one-side-only"),
        ),
    ),
    (
        "(A ∩ B) ∪ C^c",
        lambda A, B, C, U: (A & B) | (U - C),
        True,
        (
            ("(A ∩ B) ∩ C^c", lambda A, B, C, U: (A & B) & (U - C), "union-read-as-intersection"),
            ("(A ∪ B) ∪ C^c", lambda A, B, C, U: (A | B) | (U - C), "union-read-as-intersection"),
            ("(A ∩ B) ∪ C", lambda A, B, C, U: (A & B) | C, "complement-dropped"),
        ),
    ),
    (
        "A^c ∩ (B ∪ C)",
        lambda A, B, C, U: (U - A) & (B | C),
        True,
        (
            ("A ∩ (B ∪ C)", lambda A, B, C, U: A & (B | C), "complement-dropped"),
            ("A^c ∪ (B ∪ C)", lambda A, B, C, U: (U - A) | (B | C), "union-read-as-intersection"),
            ("A^c ∩ B ∩ C", lambda A, B, C, U: (U - A) & B & C, "union-read-as-intersection"),
        ),
    ),
)

_STEM = (
    "The universe is U = {{{universe}}}. A family F = {{{names}}} of subsets of U is given by {sets}. F is not a "
    "sigma-algebra; let sigma(F) be the smallest sigma-algebra on U containing F. The atoms of sigma(F) are its "
    "minimal non-empty sets. A measure mu on U is given by mu({{i}}) = w_i, where {weights}.",
    "Let U = {{{universe}}} and let F = {{{names}}} be the family of subsets {sets}. The smallest sigma-algebra "
    "containing F is written sigma(F), and its atoms are its minimal non-empty sets. A measure mu on U has "
    "mu({{i}}) = w_i, with {weights}.",
    "On the finite set U = {{{universe}}}, the family F = {{{names}}} has {sets}. Write sigma(F) for the smallest "
    "sigma-algebra on U containing F; its atoms are the minimal non-empty members. The measure mu satisfies "
    "mu({{i}}) = w_i, where {weights}.",
)
_PROMPT_A = ("How many atoms does sigma(F) have?", "Find the number of atoms of sigma(F).")
_PROMPT_B = (
    "Hence find the number of sets in sigma(F).",
    "Use the atoms to find how many sets sigma(F) contains.",
)
_PROMPT_C = (
    "Hence find how many sets of sigma(F) are not members of F, that is, how many sets must be added to F.",
    "How many of the sets in sigma(F) are not already in F?",
)
_PROMPT_D = (
    "Find mu(E), where E = {expr}.",
    "The set E = {expr} belongs to sigma(F). Find mu(E).",
)


def _atoms(universe: frozenset, family: list) -> list:
    """The classes of points that lie in exactly the same members of `family`."""
    classes: dict = {}
    for point in sorted(universe):
        classes.setdefault(tuple(point in s for s in family), set()).add(point)
    return [frozenset(c) for c in classes.values()]


def _closure(universe: frozenset, family: list) -> set:
    """sigma(family) by closing under complement and pairwise union until nothing new appears."""
    sets = {frozenset(), universe, *map(frozenset, family)}
    for _ in range(2 ** len(universe)):  # every round adds a new subset, and the universe has 2^n of them
        new = {universe - s for s in sets} | {a | b for a, b in combinations(sets, 2)}
        if new <= sets:
            return sets
        sets |= new
    raise VerificationError("the closure did not settle")


def _fmt_set(s) -> str:
    return "{" + ", ".join(str(i) for i in sorted(s)) + "}"


def _build(rng: random.Random) -> dict:
    n = rng.choice(_UNIVERSE_SIZES)
    universe = frozenset(range(1, n + 1))
    for _ in attempts(2000, "a family whose generated sigma-algebra has 3 to 8 atoms"):
        size_f = rng.choice((2, 3))
        names = "ABC"[:size_f]
        family = [frozenset(rng.sample(sorted(universe), rng.randint(2, n - 2))) for _ in range(size_f)]
        if len(set(family)) < size_f or any(universe - s in family for s in family):
            continue
        atoms = _atoms(universe, family)
        if not 4 <= len(atoms) <= 8:
            continue
        pool = [t for t in _TEMPLATES if size_f == 3 or not t[2]]
        text, ev, _needs_c, wrong_forms = rng.choice(pool)
        padded = family + [frozenset()] * (3 - size_f)
        e_set = ev(*padded, universe)
        if e_set in family or not e_set or e_set == universe:
            continue
        break
    weights = {i: rng.randint(1, 9) for i in sorted(universe)}

    # Second route: close F under complement and union and compare with the atom count.
    generated = _closure(universe, family)
    r = len(atoms)
    check(len(generated) == 2**r, "closure size is not 2^(atoms)")
    check(
        {s for s in generated if s and not any(t and t < s for t in generated)} == set(atoms),
        "the minimal sets of the closure are not the atoms",
    )
    check(e_set in generated, "E is not in sigma(F)")
    size = 2**r
    missing = size - size_f
    mu_e = sum(weights[i] for i in e_set)
    check(missing == len(generated - set(family)), "the number of sets to add disagrees with the closure")

    a_wrong = [
        (size_f, "counts-generators-as-atoms"),
        (r - 1, "misses-the-outside-atom"),
        (n, "counts-points-as-atoms"),
        (2**size_f, "counts-empty-atoms"),
        (r + 1, "counts-empty-atoms"),
    ]
    b_wrong = [
        (size - 1, "omits-the-empty-set"),
        (r * r, "squares-instead-of-powering"),
        (2 * r, "doubles-instead-of-powering"),
        (2**n, "takes-whole-power-set"),
        (2**size_f, "counts-generator-patterns-as-sets"),
    ]
    c_wrong = [
        (size, "does-not-remove-given-sets"),
        (size - size_f - 2, "assumes-empty-and-whole-present"),
        (r - size_f, "confuses-atoms-with-members"),
        (size - 1, "omits-the-empty-set"),
    ]
    d_wrong = []
    total = sum(weights.values())
    for _text, wev, tag in wrong_forms:
        d_wrong.append((sum(weights[i] for i in wev(*padded, universe)), tag))
    d_wrong.append((total - mu_e, "complement-for-set"))
    d_wrong += [(mu_e + 1, "off-by-one-count"), (mu_e - 1, "off-by-one-count"), (total, "off-by-one-count")]
    d_wrong = [(v, t) for v, t in d_wrong if v >= 1]

    sets_text = "; ".join(f"{nm} = {_fmt_set(s)}" for nm, s in zip(names, family))
    stem = phrase(
        rng,
        _STEM,
        universe=", ".join(str(i) for i in sorted(universe)),
        names=", ".join(names),
        sets=sets_text,
        weights=", ".join(f"w_{i} = {weights[i]}" for i in sorted(universe)),
    )
    parts = [
        build_part(
            phrase(rng, _PROMPT_A),
            r,
            kind="number",
            marks=2,
            working=[
                "Two points are in the same atom exactly when they lie in the same members of F.",
                f"The atoms are {', '.join(_fmt_set(a) for a in sorted(atoms, key=sorted))}: {r} of them.",
            ],
            wrong=a_wrong,
        ),
        build_part(
            phrase(rng, _PROMPT_B),
            size,
            kind="number",
            marks=1,
            working=[
                f"Every member of sigma(F) is a union of atoms, chosen freely, so there are 2^{r} = {size} of them."
            ],
            wrong=b_wrong,
            follow_through="2**part_a",
        ),
        build_part(
            phrase(rng, _PROMPT_C),
            missing,
            kind="number",
            marks=1,
            working=[f"F has {size_f} sets, so {size} - {size_f} = {missing} sets must be added."],
            wrong=c_wrong,
            follow_through=f"part_b - {size_f}",
        ),
        build_part(
            phrase(rng, _PROMPT_D, expr=text),
            mu_e,
            kind="number",
            marks=2,
            working=[f"E = {_fmt_set(e_set)}, so mu(E) is the sum of the weights of its points = {mu_e}."],
            wrong=d_wrong,
        ),
    ]
    return dict(text=stem, latex=f"plain:{stem}", parts=parts)


@generator("exd_x_r2h_sigma_generated_chain", level=19, presets={"exam": dict(tier="exam")})
def exd_x_r2h_sigma_generated_chain(rng: random.Random, tier: str = "exam") -> dict:
    """Atoms of a generated sigma-algebra, its size, how many sets to add, and the measure of a derived set."""
    check(tier == "exam", "exd_x_r2h_sigma_generated_chain: only the exam tier exists")
    return _build(rng)
